mapper.insert:

			SELECT SEQ_MEMBER.nextval FROM DUAL

    insert into RECORD_ANALYSIS_GROUP(
      GROUP_NO, STUDENT_NO, STATUS
    ) VALUES(
      #{groupNo}
      ,#{studentNo}
      ,#{status}
    )

mapper.update:
update RECORD_ANALYSIS_GROUP
set(
  COMPLETED_AT = SYSDATE
  ,status = #{status}
)
where GROUP_NO = #{groupNo}

mapper.select:
select count(*)
from RECORD_ANALYSIS_GROUP
where STUDENT_NO = #{studentNo}
and STATUS = #{status}
